import type { ReactNode } from 'react';
import {
  imageNamePattern,
  type ArticleDocument,
  type DocumentNode,
} from '@inkling/contracts';
import { stableJson } from './draft-store';

function textOf(node: DocumentNode): string {
  if (node.type === 'hardBreak') return '\n';
  return node.text ?? node.content?.map(textOf).join('') ?? '';
}
// Workspace image tags are generated by the editor. Leave other raw Markdown
// readable and never load arbitrary HTML or remote media in a version preview.
function inlinePreview(text: string): ReactNode {
  const parts: ReactNode[] = [];
  let end = 0;
  for (const match of text.matchAll(/<img\b[^<>]*>/gi)) {
    const template = document.createElement('template');
    template.innerHTML = match[0];
    const image = template.content.firstElementChild;
    const src = image?.getAttribute('src') ?? '';
    const name = src.slice('inkling-image:'.length);
    if (!src.startsWith('inkling-image:') || !imageNamePattern.test(name))
      continue;
    parts.push(text.slice(end, match.index));
    parts.push(
      <img
        key={match.index}
        src={'/api/images/' + name}
        alt={image?.getAttribute('alt') ?? '图片'}
        title={image?.getAttribute('title') ?? undefined}
        width={imageDimension(image, 'width')}
        height={imageDimension(image, 'height')}
        style={{ maxWidth: '100%' }}
      />,
    );
    end = match.index + match[0].length;
  }
  return end ? [...parts, text.slice(end)] : text;
}
function imageDimension(image: Element | null, name: string) {
  const value = image?.getAttribute(name);
  return value && /^\d+$/.test(value) ? value : undefined;
}
function alignment(node: DocumentNode) {
  const value = node.attrs?.align;
  return value === 'left' || value === 'center' || value === 'right'
    ? value
    : undefined;
}
function orderedType(value: unknown) {
  return value === '1' ||
    value === 'a' ||
    value === 'A' ||
    value === 'i' ||
    value === 'I'
    ? value
    : undefined;
}
function renderNode(node: DocumentNode): ReactNode {
  let content: ReactNode =
    node.text ??
    node.content?.map((child, index) => (
      <DocumentPart key={index} node={child} />
    ));
  for (const mark of [...(node.marks ?? [])].reverse()) {
    switch (mark.type) {
      case 'bold':
        content = <strong>{content}</strong>;
        break;
      case 'italic':
        content = <em>{content}</em>;
        break;
      case 'strike':
        content = <s>{content}</s>;
        break;
      case 'underline':
        content = <u>{content}</u>;
        break;
      case 'code':
        content = <code>{content}</code>;
        break;
      case 'link':
        content = (
          <span className="preview-link" title={mark.attrs?.href ?? ''}>
            {content}
          </span>
        );
        break;
    }
  }
  switch (node.type) {
    case 'doc':
    case 'text':
      return content;
    case 'md:paragraph':
      return <p>{inlinePreview(textOf(node))}</p>;
    case 'md:atx-heading':
    case 'md:setext-heading':
      return <h4>{inlinePreview(textOf(node).replace(/^#{1,6}\s+/, ''))}</h4>;
    case 'md:footnote':
    case 'md:block-quote':
      return <blockquote>{content}</blockquote>;
    case 'paragraph':
      return <p>{content ?? <br />}</p>;
    case 'heading':
      return node.attrs?.level === 2 ? <h4>{content}</h4> : <h5>{content}</h5>;
    case 'blockquote':
      return <blockquote>{content}</blockquote>;
    case 'md:task-list':
    case 'md:bullet-list':
    case 'bulletList':
      return <ul>{content}</ul>;
    case 'md:order-list':
    case 'orderedList':
      return (
        <ol
          start={typeof node.attrs?.start === 'number' ? node.attrs.start : 1}
          type={orderedType(node.attrs?.type)}
        >
          {content}
        </ol>
      );
    case 'md:list-item':
    case 'md:task-list-item':
    case 'listItem':
      return <li>{content}</li>;
    case 'md:table':
    case 'table':
      return (
        <div className="tableWrapper">
          <table>
            <tbody>
              {node.type === 'table'
                ? content
                : node.content?.map((row, i) => {
                    const Cell = i === 0 ? 'th' : 'td';
                    return (
                      <tr key={i}>
                        {row.content?.map((cell, j) => (
                          <Cell key={j} style={{ textAlign: alignment(cell) }}>
                            {inlinePreview(textOf(cell))}
                          </Cell>
                        ))}
                      </tr>
                    );
                  })}
            </tbody>
          </table>
        </div>
      );
    case 'tableRow':
      return <tr>{content}</tr>;
    case 'tableCell':
    case 'tableHeader': {
      const Cell = node.type === 'tableHeader' ? 'th' : 'td';
      return (
        <Cell
          colSpan={Number(node.attrs?.colspan ?? 1)}
          rowSpan={Number(node.attrs?.rowspan ?? 1)}
          style={{ textAlign: alignment(node) }}
        >
          {content}
        </Cell>
      );
    }
    case 'mermaidBlock':
      return <pre aria-label="流程图源码">{content}</pre>;
    case 'formulaBlock':
      return <pre aria-label="公式源码">{content}</pre>;
    case 'codeBlock':
      return (
        <pre>
          <code>{content}</code>
        </pre>
      );
    case 'hardBreak':
      return <br />;
    case 'md:thematic-break':
    case 'horizontalRule':
      return <hr />;
    default:
      return <pre>{textOf(node)}</pre>;
  }
}
export function DocumentPart({ node }: { node: DocumentNode }) {
  return renderNode(node);
}
export function DocumentComparison({
  local,
  remote,
}: {
  local: ArticleDocument;
  remote: ArticleDocument;
}) {
  const left = local.doc.content ?? [],
    right = remote.doc.content ?? [];
  const differences: string[] = [];
  if (local.title !== remote.title) differences.push('标题不同');
  for (let index = 0; index < Math.max(left.length, right.length); index++) {
    const a = left[index],
      b = right[index];
    if (stableJson(a ?? null) === stableJson(b ?? null)) continue;
    differences.push(
      `第 ${index + 1} 段：${!a || !b ? '段落数量不同' : textOf(a) !== textOf(b) ? '文字不同' : '格式或结构不同'}`,
    );
  }
  return (
    <>
      <ul className="difference-summary" aria-label="差异摘要">
        {differences.length ? (
          differences.map((item) => <li key={item}>{item}</li>)
        ) : (
          <li>两份内容一致</li>
        )}
      </ul>
      <div className="comparison-columns">
        <section aria-label="本页草稿预览">
          <h3>本页草稿</h3>
          <h4>{local.title || '未命名文章'}</h4>
          <DocumentPart node={local.doc} />
        </section>
        <section aria-label="服务器版本预览">
          <h3>服务器版本</h3>
          <h4>{remote.title || '未命名文章'}</h4>
          <DocumentPart node={remote.doc} />
        </section>
      </div>
    </>
  );
}
